Input Example: "this is a practice string to learn the parsing of strings"
Candidate Approach & Code:
"""
"""
Create a program to parse a given string and return a dictionary with all the words and their frequency
"""

def parse_string(string):
    words = string.split()
    word_dict = {}
    for word in words:
        if word in word_dict:
            word_dict[word] += 1
        else:
            word_dict[word] = 1
    return word_dict

